<?php
require_once __DIR__ . '/../Database/ProjectRepository.php';
require_once __DIR__ . '/NotificationService.php';

class ProjectService {
    private $repo; private $notifications;
    public function __construct($repo=null,$notifications=null){$this->repo=$repo?:new ProjectRepository();$this->notifications=$notifications?:new NotificationService();}
    private function id($prefix){return $prefix.bin2hex(random_bytes(8));}
    private function allowedStatus($status){return in_array($status,array('Planned','Active','On Hold','Completed','Cancelled'),true);}
    private function validateDate($date){if($date===null||$date==='')return null;$d=DateTime::createFromFormat('Y-m-d',$date);return $d&&$d->format('Y-m-d')===$date?$date:false;}
    public function canAccess($user,$projectId){if(!$user)return false;if(has_permission($user,'manage_projects'))return (bool)$this->repo->find($projectId);if(!has_permission($user,'view_projects'))return false;return $this->repo->hasAccess($projectId,$user['id']);}
    public function canManage($user,$project){return $user && (has_permission($user,'manage_projects') || (($project['leader_user_id']??'')===$user['id']));}
    public function listProjects($user){if(!has_permission($user,'view_projects')&&!has_permission($user,'manage_projects'))throw new RuntimeException('Permission denied: view_projects');return has_permission($user,'manage_projects')?$this->repo->listAll():$this->repo->listForUser($user['id']);}
    public function getProject($user,$projectId){$p=$this->repo->find($projectId);if(!$p)throw new OutOfBoundsException('Project not found.');if(!$this->canAccess($user,$projectId))throw new DomainException('You do not have access to this project.');$p['tasks']=$this->repo->tasks($projectId);$p['files']=$this->repo->files($projectId);$p['papers']=$this->repo->papers($projectId);$p['members']=$this->repo->members($projectId);$p['comments']=$this->repo->comments($projectId);$p['activity']=$this->repo->activity($projectId);$p['canManage']=$this->canManage($user,$p);$p['canComment']=has_permission($user,'comment_projects')||$p['canManage'];return $p;}
    public function createProject($user,$input){if(!has_permission($user,'manage_projects'))throw new DomainException('Permission denied: manage_projects');$data=$this->normalize($input);$data['id']=$this->id('p-');$p=$this->repo->create($data);$this->repo->logActivity($p['id'],$user['id'],'project_created','Created project “'.$p['name'].'”.');if(!empty($p['leader_user_id'])){$this->repo->addMember($p['id'],$p['leader_user_id'],'Project Lead');$this->notifications->projectAssigned($p['leader_user_id'],$p['name'],$p['id']);}$this->audit($user,'project_created',$p['id'],'Created '.$p['name']);return $p;}
    public function updateProject($user,$projectId,$input){$p=$this->repo->find($projectId);if(!$p)throw new OutOfBoundsException('Project not found.');if(!$this->canManage($user,$p))throw new DomainException('Permission denied: manage project');$data=$this->normalize($input,$p);$oldLeader=$p['leader_user_id'];$updated=$this->repo->update($projectId,$data);$this->repo->logActivity($projectId,$user['id'],'project_updated','Updated project details/status.');if($updated['leader_user_id']&&$updated['leader_user_id']!==$oldLeader){$this->repo->addMember($projectId,$updated['leader_user_id'],'Project Lead');$this->notifications->projectAssigned($updated['leader_user_id'],$updated['name'],$projectId);$this->repo->logActivity($projectId,$user['id'],'leader_changed','Assigned project leader '.$updated['leader_name'].'.');}$this->audit($user,'project_updated',$projectId,'Updated '.$updated['name']);return $updated;}
    private function normalize($input,$current=array()){$name=trim(isset($input['name'])?$input['name']:($current['name']??''));if($name==='')throw new InvalidArgumentException('Project name is required.');if(strlen($name)>220)throw new InvalidArgumentException('Project name is too long.');$status=trim(isset($input['status'])?$input['status']:($current['status']??'Active'));if(!$this->allowedStatus($status))throw new InvalidArgumentException('Invalid project status.');$start=$this->validateDate(isset($input['startDate'])?$input['startDate']:($current['start_date']??null));$end=$this->validateDate(isset($input['endDate'])?$input['endDate']:($current['end_date']??null));if($start===false||$end===false)throw new InvalidArgumentException('Dates must use YYYY-MM-DD.');if($start&&$end&&$end<$start)throw new InvalidArgumentException('End date cannot be before start date.');$leader=trim(isset($input['leaderUserId'])?(string)$input['leaderUserId']:(string)($current['leader_user_id']??''));if($leader!==''){$u=$this->repo->user($leader);if(!$u||$u['status']!=='Active')throw new InvalidArgumentException('Project leader must be an active RDI user.');}else $leader=null;return array('name'=>$name,'description'=>substr(trim(isset($input['description'])?$input['description']:($current['description']??'')),0,20000),'leader_user_id'=>$leader,'start_date'=>$start?:null,'end_date'=>$end?:null,'status'=>$status);}
    public function setUserProjects($user,$targetUserId,$projectIds){if(!has_permission($user,'assign_projects'))throw new DomainException('Permission denied: assign_projects');$target=$this->repo->user($targetUserId);if(!$target)throw new OutOfBoundsException('User not found.');$all=$this->repo->listAll();$valid=array();foreach($all as $p)$valid[$p['id']]=$p;$wanted=array();foreach(array_unique(is_array($projectIds)?$projectIds:array()) as $pid)if(isset($valid[$pid]))$wanted[]=$pid;$old=$this->repo->projectIdsForUser($targetUserId);foreach(array_diff($old,$wanted) as $pid){if(($valid[$pid]['leader_user_id']??'')===$targetUserId)continue;$this->repo->removeMember($pid,$targetUserId);$this->repo->logActivity($pid,$user['id'],'member_removed','Removed '.$target['name'].' from the project.');}foreach($wanted as $pid){$already=in_array($pid,$old,true);$role=(($valid[$pid]['leader_user_id']??'')===$targetUserId)?'Project Lead':'Member';$this->repo->addMember($pid,$targetUserId,$role);if(!$already){$this->repo->logActivity($pid,$user['id'],'member_added','Added '.$target['name'].' as '.$role.'.');$this->notifications->projectAssigned($targetUserId,$valid[$pid]['name'],$pid);}}audit_log('user_projects_changed','user',$targetUserId,'Project memberships updated',$user);return $this->repo->projectIdsForUser($targetUserId);}
    public function addMember($user,$projectId,$userId,$role='Member'){$p=$this->repo->find($projectId);if(!$p)throw new OutOfBoundsException('Project not found.');if(!$this->canManage($user,$p)&&!has_permission($user,'assign_projects'))throw new DomainException('Permission denied: assign_projects');$target=$this->repo->user($userId);if(!$target||$target['status']!=='Active')throw new InvalidArgumentException('Member must be an active RDI user.');$role=trim($role?:'Member');if(strlen($role)>100)throw new InvalidArgumentException('Membership role is too long.');$already=$this->repo->memberExists($projectId,$userId);$this->repo->addMember($projectId,$userId,$role);$this->repo->logActivity($projectId,$user['id'],$already?'member_updated':'member_added',($already?'Updated ':'Added ').$target['name'].' as '.$role.'.');if(!$already)$this->notifications->projectAssigned($userId,$p['name'],$projectId);$this->audit($user,$already?'project_member_updated':'project_member_added',$projectId,$target['name'].' · '.$role);return $this->repo->members($projectId);}
    public function removeMember($user,$projectId,$userId){$p=$this->repo->find($projectId);if(!$p)throw new OutOfBoundsException('Project not found.');if(!$this->canManage($user,$p)&&!has_permission($user,'assign_projects'))throw new DomainException('Permission denied: assign_projects');if($p['leader_user_id']===$userId)throw new InvalidArgumentException('Change the project leader before removing them from membership.');$target=$this->repo->user($userId);$this->repo->removeMember($projectId,$userId);$this->repo->logActivity($projectId,$user['id'],'member_removed','Removed '.($target?$target['name']:$userId).' from the project.');$this->audit($user,'project_member_removed',$projectId,$target?$target['name']:$userId);return $this->repo->members($projectId);}
    public function addComment($user,$projectId,$message,$parentId=null){if(!$this->canAccess($user,$projectId))throw new DomainException('You do not have access to this project.');if(!has_permission($user,'comment_projects')&&!has_permission($user,'manage_projects'))throw new DomainException('Permission denied: comment_projects');$message=trim($message);if($message===''||strlen($message)>5000)throw new InvalidArgumentException('Comment must be between 1 and 5000 characters.');if($parentId){$parent=$this->repo->comment($parentId);if(!$parent||$parent['project_id']!==$projectId)throw new InvalidArgumentException('Reply target is not part of this project.');}$id=$this->id('pc-');$this->repo->addComment(array('id'=>$id,'project_id'=>$projectId,'user_id'=>$user['id'],'parent_id'=>$parentId?:null,'message'=>$message));$this->repo->logActivity($projectId,$user['id'],'comment_added','Added a project discussion comment.');$this->audit($user,'project_comment_added',$projectId,'Comment '.$id);return $id;}
    public function addFile($user,$projectId,$input){$p=$this->repo->find($projectId);if(!$p)throw new OutOfBoundsException('Project not found.');if(!$this->canManage($user,$p))throw new DomainException('Permission denied: manage project');$name=trim($input['fileName']??'');$url=trim($input['fileUrl']??'');if($name===''||$url==='')throw new InvalidArgumentException('File name and file link are required in Phase 2. Real protected uploads are implemented in Phase 4.');if(strlen($name)>255)throw new InvalidArgumentException('File name is too long.');if(!preg_match('#^https?://#i',$url)&&strpos($url,'/')!==0)throw new InvalidArgumentException('File link must be an http(s) URL or an absolute application path.');$id=$this->id('pf-');$this->repo->addFile(array('id'=>$id,'project_id'=>$projectId,'file_name'=>$name,'file_url'=>$url,'description'=>trim($input['description']??''),'added_by'=>$user['id']));$this->repo->logActivity($projectId,$user['id'],'file_added','Added project file “'.$name.'”.');$this->audit($user,'project_file_added',$projectId,$name);return $id;}
    public function deleteFile($user,$projectId,$fileId){$p=$this->repo->find($projectId);if(!$p)throw new OutOfBoundsException('Project not found.');if(!$this->canManage($user,$p))throw new DomainException('Permission denied: manage project');$f=$this->repo->file($fileId);if(!$f||$f['project_id']!==$projectId)throw new OutOfBoundsException('Project file not found.');$this->repo->deleteFile($fileId);$this->repo->logActivity($projectId,$user['id'],'file_removed','Removed project file “'.$f['file_name'].'”.');$this->audit($user,'project_file_removed',$projectId,$f['file_name']);}
    public function addPaper($user,$projectId,$input){$p=$this->repo->find($projectId);if(!$p)throw new OutOfBoundsException('Project not found.');if(!$this->canManage($user,$p))throw new DomainException('Permission denied: manage project');$title=trim($input['title']??'');if($title==='')throw new InvalidArgumentException('Paper title is required.');if(strlen($title)>255)throw new InvalidArgumentException('Paper title is too long.');$paperUrl=trim($input['paperUrl']??'');if($paperUrl!==''&&!preg_match('#^https?://#i',$paperUrl))throw new InvalidArgumentException('Paper link must use http or https.');$id=$this->id('pp-');$this->repo->addPaper(array('id'=>$id,'project_id'=>$projectId,'title'=>$title,'authors'=>trim($input['authors']??''),'venue'=>trim($input['venue']??''),'doi'=>trim($input['doi']??''),'paper_url'=>$paperUrl,'notes'=>trim($input['notes']??''),'added_by'=>$user['id']));$this->repo->logActivity($projectId,$user['id'],'paper_added','Added research paper “'.$title.'”.');$this->audit($user,'project_paper_added',$projectId,$title);return $id;}
    public function deletePaper($user,$projectId,$paperId){$p=$this->repo->find($projectId);if(!$p)throw new OutOfBoundsException('Project not found.');if(!$this->canManage($user,$p))throw new DomainException('Permission denied: manage project');$paper=$this->repo->paper($paperId);if(!$paper||$paper['project_id']!==$projectId)throw new OutOfBoundsException('Research paper not found.');$this->repo->deletePaper($paperId);$this->repo->logActivity($projectId,$user['id'],'paper_removed','Removed research paper “'.$paper['title'].'”.');$this->audit($user,'project_paper_removed',$projectId,$paper['title']);}
    public function activeUsers($user){if(!has_permission($user,'manage_projects')&&!has_permission($user,'assign_projects'))return array();return $this->repo->activeUsers();}
    public function activeUsersForProject($user,$projectId){$p=$this->repo->find($projectId);if(!$p||!$this->canManage($user,$p))return array();return $this->repo->activeUsers();}
    public function recordTaskActivity($actor,$projectId,$action,$details){if(!$projectId)return;try{$p=$this->repo->find($projectId);if(!$p)return;$this->repo->logActivity($projectId,$actor?$actor['id']:null,$action,$details);}catch(Throwable $e){error_log('[RDI project activity] '.$e->getMessage());}}
    private function audit($user,$action,$projectId,$details){audit_log($action,'project',$projectId,$details,$user);}
}
